// Get expected score for a given state
// Returns 0.0 if state not found (shouldn't happen for valid states)
inline double get_expected_score(int upper_sum, int used_hands) {
    auto it = dp_table.find({upper_sum, used_hands});
    return (it != dp_table.end()) ? it->second : 0.0;
}

// Get expected score from initial state (no categories used, upper sum = 0)
inline double get_initial_expected_score() {
    return get_expected_score(0, 0);
}

